{"file_path":"/work/tests/test_metrics.py","content":"from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_treats_none_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3


def test_monitor_flag_rate_empty_list():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_by_transcript_count():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
    }
    assert pooled_flag_rate(groups) == 0.25


def test_pooled_flag_rate_no_transcripts():
    assert pooled_flag_rate({"a": [], "b": []}) == 0.0


def test_flags_in_window_uses_last_n_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7


def test_flags_in_window_handles_zero_and_long_windows():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_skips_comments_and_blank_lines_and_parses_none():
    lines = ["  ", " # comment", " x1 , 3 , ", "x2,4,0"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]


def test_parse_transcript_log_error_reports_original_line_number():
    lines = ["", "# comment", "x1,nope,1"]
    try:
        parse_transcript_log(lines)
    except ValueError as exc:
        assert "line 3" in str(exc)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "b", "day": 4, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 3, "flagged": False},
    ]


def test_daily_flag_counts_respects_range_and_falsey_flags():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 1, "flagged": None},
        {"id": "c", "day": 2, "flagged": False},
        {"id": "d", "day": 3, "flagged": True},
        {"id": "e", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 1, 0]


def test_daily_flag_counts_empty_when_end_before_start():
    assert daily_flag_counts([], 3, 2) == []


def test_monitor_summary_matches_spec():
    groups = {
        "a": [{"id": "a1", "day": 1, "flagged": True}, {"id": "a2", "day": 3, "flagged": False}],
        "b": [],
        "c": [{"id": "c1", "day": 2, "flagged": True}],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "beta": [{"flagged": True}, {"flagged": False}],
        "alpha": [{"flagged": True}, {"flagged": False}],
        "gamma": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["alpha", "beta", "gamma"]


def test_flag_rate_by_group_sorted_and_empty_group_none():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [],
    }
    assert flag_rate_by_group(groups) == {"a": None, "b": 0.5}


def test_longest_flag_streak_resets_on_zero():
    assert longest_flag_streak([1, 2, 0, 3, 4]) == 2
